# Replace the caption text and the note block of `file` with its TABLE_TEXT entry.
apply_table_text <- function(file) {
  key <- sub("\\.tex$", "", basename(file))
  e <- TABLE_TEXT[[key]]
  if (is.null(e) || !file.exists(file)) return(invisible(file))
  tx <- readLines(file, warn = FALSE)
  ic <- grep("\\caption{", tx, fixed = TRUE)[1L]
  tx[ic] <- sub("\\\\textbf\\{.*\\}\\}", paste0("\\\\textbf{", gsub("\\\\", "\\\\\\\\", e$caption), "}}"), tx[ic])
  i <- grep("\\begin{minipage}{\\linewidth}\\footnotesize", tx, fixed = TRUE)
  i <- i[length(i)]
  j <- grep("\\end{minipage}", tx, fixed = TRUE)
  j <- j[j > i][1L]
  stars <- any(grepl("^{*", tx[seq_len(i)], fixed = TRUE))
  blk <- paste0("\\textit{Notes:} ", e$note)
  if (stars) blk <- c(blk, "\\newline", SIG_LINE)
  writeLines(c(tx[seq_len(i)], blk, tx[j:length(tx)]), file)
  invisible(file)
}
